window.AUTH=window.AUTH||{};window.AUTH["22-200"]={"d":"22-200","id":"2022/22-200","n":"Slack Technologies v. Pirani","briefs":[{"k":"petitioner","label":"Brief of petitioners Slack Technologies, LLC, et al.","date":"2023-01-27","url":"https://www.supremecourt.gov/DocketPDF/22/22-200/253319/20230127144311686_22-200%20Brief%20for%20Petitioners.pdf","side":"pet","n":91},{"k":"respondent","label":"Brief of respondent Fiyyaz Pirani","date":"2023-02-27","url":"https://www.supremecourt.gov/DocketPDF/22/22-200/255668/20230227145956696_22-200%20bs.pdf","side":"res","n":71},{"k":"reply","label":"Reply of petitioners Slack Technologies, LLC, et al.","date":"2023-03-29","url":"https://www.supremecourt.gov/DocketPDF/22/22-200/260188/20230329134840061_22-200%20Reply%20Brief%20for%20Petitioners.PDF","side":"pet","n":44}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us2r31_5h26.pdf","tr":true,"items":[{"t":"case","label":"Abbey v. Comput. Memories, Inc.","cite":"634 F. Supp. 870","y":1986,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./634/870/","by":{"0":"32"}},{"t":"case","label":"APA Excelsior III L.P. v. Premiere Techs., Inc.","cite":"476 F.3d 1261","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/476/1261/","op":1,"by":{"0":"32"}},{"t":"case","label":"Ballay v. Legg Mason Wood Walker, Inc.","cite":"925 F.2d 682","y":1991,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/925/682/","by":{"0":"27, 42"}},{"t":"case","label":"Barnes v. Osofsky","cite":"373 F.2d 269","y":1967,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/373/269/","op":4,"ar":4,"sum":"Noting possibility of shifting tracing burden.","sumSrc":"brief:1","by":{"0":"4, 14, 15, 23, 24, 25, 30, 32, 35, 47, 25, 26, 29, 33","1":"19, 23, 35-38, 49","2":"5, 6, 8, 16, 18, 19, 21, 6"}},{"t":"case","label":"Berckeley Inv. Grp., Ltd. v. Colkitt","cite":"455 F.3d 195","y":2006,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/455/195/","by":{"0":"44"}},{"t":"case","label":"Blue Chip Stamps v. Manor Drug Stores","cite":"421 U.S. 723","y":1975,"id":"1974/74-124","sc":1,"op":1,"sum":"A private damages action under Rule 10b-5 is confined to actual purchasers or sellers of securities and the Birnbaum rule bars respondent from maintaining this suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5","2":"16"}},{"t":"case","label":"Cal. Pub. Emps.’ Ret. Sys. v. ANZ Sec., Inc.","cite":"137 S. Ct. 2042","y":2017,"id":"2016/16-373","sc":1,"sum":"The Court determined that the filing of a putative class action lawsuit does not satisfy the three-year time limit in Section 13 of the Securities Act with respect to the individual claims of other class members.","sumSrc":"Oyez","by":{"0":"38","1":"28"}},{"t":"case","label":"Cal. Pub. Emps.’ Ret. Sys. v. Chubb Corp.","cite":"394 F.3d 126","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/394/126/","by":{"0":"31, 32"}},{"t":"case","label":"Chiarella v. United States","cite":"445 U.S. 222","y":1980,"id":"1979/78-1202","sc":1,"sum":"A duty to disclose information arises if there is a relationship of trust and confidence between parties to the transaction. Chiarella had no such duty. He was not a corporate insider in the acquiring corporation and he did not receive confidential information from the target company.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Colonial Realty Corp. v. Brunswick Corp.","cite":"257 F. Supp. 875","y":1966,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./257/875/","by":{"0":"24, 32, 35"}},{"t":"case","label":"CTS Corp. v. Waldburger","cite":"573 U.S. 1","y":2014,"id":"2013/13-339","sc":1,"sum":"The Court found that the Comprehensive Environmental Response, Compensation, and Liability Act pre-empts statutes of limitations, but cannot be used to pre-empt statutes of repose.","sumSrc":"Oyez","by":{"0":"18, 39"}},{"t":"case","label":"Ernst & Ernst v. Hochfelder","cite":"425 U.S. 185","y":1976,"id":"1975/74-1042","sc":1,"sum":"Petitioner accounting firm was retained to audit periodically a brokerage firm's books and records. Respondents, who were customers of the brokerage firm, invested in a securities scheme ultimately revealed as fraudulent and perpetrated by the firm's president and principal stockholder. After the fraud came to light, respondents filed an action for damages against petitioner under § 10 (b) of the Securities Exchange …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 39, 42","1":"33"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"0":"28","2":"3, 6, 7"}},{"t":"case","label":"Fischman v. Raytheon Mfg. Co.","cite":"188 F.2d 783","y":1951,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/188/783/","by":{"0":"24"}},{"t":"case","label":"Gen. Dynamics Land Sys., Inc. v. Cline","cite":"540 U.S. 581","y":2004,"id":"2003/02-1080","sc":1,"sum":"Justice David H. Souter delivered the Court's 6-3 opinion that the Age Discrimination in Employment Act's \"text, structure, purpose, history, and relationship to other federal statutes show that the statute does not mean to stop an employer from favoring an older employee over a younger one.\" The Court cited a long-held understanding of the \"ADEA as a remedy for unfair preference based on relative youth, leaving complaints of the relatively young outside the statutory concern.\" The Court also noted the findings section of the act included no evidence of younger workers being discriminated against in favor of older workers.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Gibb v. Delta Drilling Co.","cite":"104 F.R.D. 59","y":1984,"court":"N.D. Tex.","url":"https://www.courtlistener.com/c/F.R.D./104/59/","by":{"0":"32"}},{"t":"case","label":"Guenther v. Cooper Life Scis., Inc.","cite":"759 F. Supp. 1437","y":1990,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./759/1437/","by":{"0":"32"}},{"t":"case","label":"Gustafson v. Alloyd Co.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"op":1,"ar":28,"sum":"Petitioners (collectively Gustafson), the sole shareholders of Alloyd, Inc., sold substantially all of its stock to respondents and other buyers in a private sale agreement. The purchase price included a payment reflecting an estimated increase in the company's net worth from the end of the previous year through the closing, since hard financial data were unavailable. The contract provided that if a year-end audit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 6, 13, 15, 16, 19, 26, 28, 30","1":"16, 19, 32, 34, 41-44","2":"11, 12, 13, 17, 12"}},{"t":"case","label":"Harden v. Raffensperger, Hughes & Co.","cite":"933 F. Supp. 763","y":1996,"court":"S.D. Ind.","url":"https://www.courtlistener.com/c/F.%20Supp./933/763/","by":{"0":"32"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"op":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"0":"38, 39"}},{"t":"case","label":"Herman & MacLean v. Huddleston","cite":"459 U.S. 375","y":1983,"id":"1982/81-680","sc":1,"op":3,"ar":2,"sum":"Alleging that they were defrauded by misrepresentations in a registration statement and prospectus for certain securities, purchasers of such securities brought a class action in Federal District Court against most of the participants in the offering, seeking recovery under § 10(b) of the Securities Exchange Act of 1934 (1934 Act), which makes it unlawful for \"any\" person to use \"any\" manipulative or deceptive …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6, 14, 16, 20, 29, 31, 34, 37, 41, 34","1":"4, 6, 20, 21, 33-35","2":"15, 17"}},{"t":"case","label":"Hertzberg v. Dignity Partners, Inc.","cite":"191 F.3d 1076","y":1999,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/191/1076/","op":1,"by":{"0":"32, 34"}},{"t":"case","label":"Jensen v. iShares Trust","cite":"44 Cal. App. 5th 618","y":2020,"url":"https://www.courtlistener.com/c/Cal.%20App.%205th/44/618/","by":{"0":"36","2":"18"}},{"t":"case","label":"Joseph v. Wiles","cite":"223 F.3d 1155","y":2000,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/223/1155/","op":1,"by":{"0":"31, 33"}},{"t":"case","label":"Kokesh v. SEC","cite":"581 U.S. 455","y":2017,"id":"2016/16-529","sc":1,"sum":"The Court held that Securities and Exchange Commission (SEC) disgorgement functions as a penalty, and therefore is subject to the five-year statute of limitations.Commission seeking “disgorgement,” or payment, of illegally obtained funds.","sumSrc":"Oyez","by":{"0":"4"}},{"t":"case","label":"Krim v. pcOrder.com, Inc.","cite":"402 F.3d 489","y":2005,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/402/489/","ar":3,"by":{"0":"31, 33, 36","1":"36, 47, 48","2":"18, 19, 22"}},{"t":"case","label":"Lee v. Ernst & Young, LLP","cite":"294 F.3d 969","y":2002,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/294/969/","op":1,"by":{"0":"31, 33, 35"}},{"t":"case","label":"Maldonado v. Dominguez","cite":"137 F.3d 1","y":1998,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/137/1/","by":{"0":"6"}},{"t":"case","label":"McFarland v. Memorex Corp.","cite":"493 F. Supp. 631","y":1980,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./493/631/","by":{"0":"32"}},{"t":"case","label":"Monessen Sw. Ry. Co. v. Morgan","cite":"486 U.S. 330","y":1988,"id":"1987/86-1743","sc":1,"sum":"Appellee suffered a permanent back injury while working as a brakeman and conductor for appellant railroad. After returning to work in a less physically demanding position, appellee brought an action under the Federal Employers' Liability Act (FELA) in a Pennsylvania state court, alleging that his injury was attributable to appellant's negligence and that his future earning power had been impaired as a result of his …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 31","2":"17"}},{"t":"case","label":"Pinter v. Dahl","cite":"486 U.S. 622","y":1988,"id":"1987/86-805","sc":1,"sum":"Petitioner Pinter, an oil and gas producer and registered securities dealer, sold unregistered securities consisting of fractional undivided interests in oil and gas leases to respondent Dahl, a real estate broker and investor who was experienced in oil and gas ventures. Dahl touted the venture to the other respondents-his friends, family, and business associates -and assisted them in completing subscription …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15, 27, 47","1":"23, 40"}},{"t":"case","label":"PPM Am., Inc. v. Marriott Corp.","cite":"820 F. Supp. 970","y":1993,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp./820/970/","by":{"0":"32"}},{"t":"case","label":"Rodriguez de Quijas v. Shearson/Am. Express, Inc.","cite":"490 U.S. 477","y":1989,"id":"1988/88-385","sc":1,"sum":"A predispute agreement to arbitrate claims under the Securities Act of 1933 is enforceable and resolution of the claims only in a judicial forum is not required.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 30, 42","2":"16, 17"}},{"t":"case","label":"SEC v. Cavanagh","cite":"155 F.3d 129","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/155/129/","by":{"0":"44"}},{"t":"case","label":"SEC v. M & A W., Inc.","cite":"538 F.3d 1043","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/538/1043/","by":{"0":"44"}},{"t":"case","label":"SEC v. Ralston Purina Co.","cite":"346 U.S. 119","y":1953,"id":"scdb/1952-105","sc":1,"sum":"These transactions were not exempted under § 4 (1) of the Act as transactions \"not involving any public offering.\"","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44","1":"49"}},{"t":"case","label":"SEC v. Sierra Brokerage Servs., Inc.","cite":"712 F.3d 321","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/712/321/","by":{"0":"44"}},{"t":"case","label":"Tellabs, Inc. v. Makor Issues & Rights, Ltd.","cite":"551 U.S. 308","y":2007,"id":"2006/06-484","sc":1,"sum":"The Court ruled by a vote of 8-1 that a securities fraud complaint must allege facts establishing an inference of guilty intent that is \"cogent and at least as compelling as any opposing inference of nonfraudulent intent.\" Justice Ruth Bader Ginsburg wrote that opinion for the Court, which held that the Seventh Circuit's more relaxed standard was not strong enough to comport with Congress's intent in PSLRA to limit securities fraud litigation. \"The strength of an inference cannot be decided in a vacuum.","sumSrc":"Oyez","by":{"0":"6"}},{"t":"case","label":"Turner v. First Wis. Mortg. Tr.","cite":"454 F. Supp. 899","y":1978,"court":"E.D. Wis.","url":"https://www.courtlistener.com/c/F.%20Supp./454/899/","ar":2,"by":{"0":"32"}},{"t":"case","label":"United States v. Naftalin","cite":"441 U.S. 768","y":1979,"id":"1978/78-561","sc":1,"sum":"Section 17 (a) (1) prohibits frauds against brokers as well as investors.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6"}},{"t":"case","label":"Wis. Cent. Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"0":"16, 29","2":"15"}},{"t":"usc","label":"15 U.S.C. § 77b","url":"https://www.law.cornell.edu/uscode/text/15/77b","subs":["(b)","(a)(10)","(a)(11)","(a)(3)"],"stext":{"head":"§77b. Definitions; promotion of efficiency, competition, and capital formation","paras":[[0,"(a) Definitions"],[0,"When used in this subchapter, unless the context otherwise requires—"],[1,"(1) The term \"security\" means any note, stock, treasury stock, security future, security-based swap, bond, debenture, evidence of indebtedness, certificate of interest or participation in any profit-sharing agreement, collateral-trust certificate, preorganization certificate or subscription, transferable share, investment contract, voting-trust certificate, certificate of deposit for a security, fractional undivided interest in oil, gas, or other mineral rights, any put, call, straddle, option, or privilege on any security, certificate of deposit, or group or index of securities (including any interest therein or based on the value thereof), or any put, call, straddle, option, or privilege entered into on a national securities exchange relating to foreign currency, or, in general, any interest or instrument commonly known as a \"security\", or any certificate of interest or participation in, temporary or interim certificate for, receipt for, guarantee of, or warrant or right to subscribe to or purchase, any of the foregoing."],[1,"(2) The term \"person\" means an individual, a corporation, a partnership, an association, a joint-stock company, a trust, any unincorporated organization, or a government or political subdivision thereof. As used in this paragraph the term \"trust\" shall include only a trust where the interest or interests of the beneficiary or beneficiaries are evidenced by a security."],[1,"(3) The term \"sale\" or \"sell\" shall include every contract of sale or disposition of a security or interest in a security, for value. The term \"offer to sell\", \"offer for sale\", or \"offer\" shall include every attempt or offer to dispose of, or solicitation of an offer to buy, a security or interest in a security, for value. The terms defined in this paragraph and the term \"offer to buy\" as used in subsection (c) of section 77e of this title shall not include preliminary negotiations or agreements between an issuer (or any person directly or indirectly controlling or controlled by an issuer, or under direct or indirect common control with an issuer) and any underwriter or among underwriters who are or are to be in privity of contract with an issuer (or any person directly or indirectly controlling or controlled by an issuer, or under direct or indirect common control with an issuer). Any security given or delivered with, or as a bonus on account of, any purchase of securities or any other thing, shall be conclusively presumed to constitute a part of the subject of such purchase and to have been offered and sold for value. The issue or transfer of a right or privilege, when originally issued or transferred with a security, giving the holder of such security the right to convert such security into another security of the same issuer or of another person, or giving a right to subscribe to another security of the same issuer or of another person, which right cannot be exercised until some future date, shall not be deemed to be an offer or sale of such other security; but the issue or transfer of such other security upon the exercise of such right of conversion or subscription shall be deemed a sale of such other security. Any offer or sale of a security futures product by or on behalf of the issuer of the securities underlying the security futures product, an affiliate of the issuer, or an underwriter, shall constitute a contract for sale of, sale of, offer for sale, or offer to sell the underlying securities. Any offer or sale of a security-based swap by or on behalf of the issuer of the securities upon which such security-based swap is based or is referenced, an affiliate of the issuer, or an underwriter, shall constitute a contract for sale of, sale of, offer for sale, or offer to sell such securities. The publication or distribution by a broker or dealer of a research report about an emerging growth company that is the subject of a proposed public offering of the common equity securities of such emerging growth company pursuant to a registration statement that the issuer proposes to file, or has filed, or that is effective shall be deemed for purposes of paragraph (10) of this subsection and section 77e(c) of this title not to constitute an offer for sale or offer to sell a security, even if the broker or dealer is participating or will participate in the registered offering of the securities of the issuer. As used in this paragraph, the term \"research report\" means a written, electronic, or oral communication that includes information, opinions, or recommendations with respect to securities of an issuer or an analysis of a security or an issuer, whether or not it provides information reasonably sufficient upon which to base an investment decision."],[1,"(4) The term \"issuer\" means every person who issues or proposes to issue any security; except that with respect to certificates of deposit, voting-trust certificates, or collateral-trust certificates, or with respect to certificates of interest or shares in an unincorporated investment trust not having a board of directors (or persons performing similar functions) or of the fixed, restricted management, or unit type, the term \"issuer\" means the person or persons performing the acts and assuming the duties of depositor or manager pursuant to the provisions of the trust or other agreement or instrument under which such securities are issued; except that in the case of an unincorporated association which provides by its articles for limited liability of any or all of its members, or in the case of a trust, committee, or other legal entity, the trustees or members thereof shall not be individually liable as issuers of any security issued by the association, trust, committee, or other legal entity; except that with respect to equipment-trust certificates or like securities, the term \"issuer\" means the person by whom the equipment or property is or is to be used; and except that with respect to fractional undivided interests in oil, gas, or other mineral rights, the term \"issuer\" means the owner of any such right or of any interest in such right (whether whole or fractional) who creates fractional interests therein for the purpose of public offering."],[1,"(5) The term \"Commission\" means the Securities and Exchange Commission."],[1,"(6) The term \"Territory\" means Puerto Rico, the Virgin Islands, and the insular possessions of the United States."],[1,"(7) The term \"interstate commerce\" means trade or commerce in securities or any transportation or communication relating thereto among the several States or between the District of Columbia or any Territory of the United States and any State or other Territory, or between any foreign country and any State, Territory, or the District of Columbia, or within the District of Columbia."],[1,"(8) The term \"registration statement\" means the statement provided for in section 77f of this title, and includes any amendment thereto and any report, document, or memorandum filed as part of such statement or incorporated therein by reference."],[1,"(9) The term \"write\" or \"written\" shall include printed, lithographed, or any means of graphic communication."],[1,"(10) The term \"prospectus\" means any prospectus, notice, circular, advertisement, letter, or communication, written or by radio or television, which offers any security for sale or confirms the sale of any security; except that (a) a communication sent or given after the effective date of the registration statement (other than a prospectus permitted under subsection (b) of section 77j of this title) shall not be deemed a prospectus if it is proved that prior to or at the same time with such communication a written prospectus meeting the requirements of subsection (a) of section 77j of this title at the time of 1 such communication was sent or given to the person to whom the communication was made, and (b) a notice, circular, advertisement, letter, or communication in respect of a security shall not be deemed to be a prospectus if it states from whom a written prospectus meeting the requirements of section 77j of this title may be obtained and, in addition, does no more than identify the security, state the price thereof, state by whom orders will be executed, and contain such other information as the Commission, by rules or regulations deemed necessary or appropriate in the public interest and for the protection of investors, and subject to such terms and conditions as may be prescribed therein, may permit."],[1,"(11) The term \"underwriter\" means any person who has purchased from an issuer with a view to, or offers or sells for an issuer in connection with, the distribution of any security, or participates or has a direct or indirect participation in any such undertaking, or participates or has a participation in the direct or indirect underwriting of any such undertaking; but such term shall not include a person whose interest is limited to a commission from an underwriter or dealer not in excess of the usual and customary distributors' or sellers' commission. As used in this paragraph the term \"issuer\" shall include, in addition to an issuer, any person directly or indirectly controlling or controlled by the issuer, or any person under direct or indirect common control with the issuer."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77b?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§77b. Definitions; promotion of efficiency, competition, and capital formation","tname":"Commerce and Trade","by":{"0":"4","1":"5, 40, 5, 30"}},{"t":"usc","label":"15 U.S.C. § 77c","url":"https://www.law.cornell.edu/uscode/text/15/77c","subs":["(a)","(a)(2)","(b)(1)"],"stext":{"head":"§77c. Classes of securities under this subchapter","paras":[[0,"(a) Exempted securities"],[0,"Except as hereinafter expressly provided, the provisions of this subchapter shall not apply to any of the following classes of securities:"],[1,"(1) Reserved."],[1,"(2) Any security issued or guaranteed by the United States or any territory thereof, or by the District of Columbia, or by any State of the United States, or by any political subdivision of a State or territory, or by any public instrumentality of one or more States or territories, or by any person controlled or supervised by and acting as an instrumentality of the Government of the United States pursuant to authority granted by the Congress of the United States; or any certificate of deposit for any of the foregoing; or any security issued or guaranteed by any bank; or any security issued by or representing an interest in or a direct obligation of a Federal Reserve bank; or any interest or participation in any common trust fund or similar fund that is excluded from the definition of the term \"investment company\" under section 3(c)(3) of the Investment Company Act of 1940 [15 U.S.C. 80a–3(c)(3)]; or any security which is an industrial development bond (as defined in section 103(c)(2) 1 of title 26) the interest on which is excludable from gross income under section 103(a)(1) 1 of title 26 if, by reason of the application of paragraph (4) or (6) of section 103(c) 1 of title 26 (determined as if paragraphs (4)(A), (5), and (7) were not included in such section 103(c)),1 paragraph (1) of such section 103(c) 1 does not apply to such security; or any interest or participation in a single trust fund, or in a collective trust fund maintained by a bank, or any security arising out of a contract issued by an insurance company, which interest, participation, or security is issued in connection with (A) a stock bonus, pension, or profit-sharing plan which meets the requirements for qualification under section 401 of title 26, (B) an annuity plan which meets the requirements for the deduction of the employer's contributions under section 404(a)(2) of title 26, (C) a governmental plan as defined in section 414(d) of title 26 which has been established by an employer for the exclusive benefit of its employees or their beneficiaries for the purpose of distributing to such employees or their beneficiaries the corpus and income of the funds accumulated under such plan, if under such plan it is impossible, prior to the satisfaction of all liabilities with respect to such employees and their beneficiaries, for any part of the corpus or income to be used for, or diverted to, purposes other than the exclusive benefit of such employees or their beneficiaries, or (D) a church plan, company, or account that is excluded from the definition of an investment company under section 3(c)(14) of the Investment Company Act of 1940 [15 U.S.C. 80a–3(c)(14)], other than any plan described in subparagraph (A), (B), (C), or (D) of this paragraph (i) the contributions under which are held in a single trust fund or in a separate account maintained by an insurance company for a single employer and under which an amount in excess of the employer's contribution is allocated to the purchase of securities (other than interests or participations in the trust or separate account itself) issued by the employer or any company directly or indirectly controlling, controlled by, or under common control with the employer, (ii) which covers employees some or all of whom are employees within the meaning of section 401(c)(1) of title 26 (other than a person participating in a church plan who is described in section 414(e)(3)(B) of title 26), or (iii) which is a plan funded by an annuity contract described in section 403(b) of title 26 (other than a retirement income account described in section 403(b)(9) of title 26, to the extent that the interest or participation in such single trust fund or collective trust fund is issued to a church, a convention or association of churches, or an organization described in section 414(e)(3)(A) of title 26 establishing or maintaining the retirement income account or to a trust established by any such entity in connection with the retirement income account). The Commission, by rules and regulations or order, shall exempt from the provisions of section 77e of this title any interest or participation issued in connection with a stock bonus, pension, profit-sharing, or annuity plan which covers employees some or all of whom are employees within the meaning of section 401(c)(1) of title 26, if and to the extent that the Commission determines this to be necessary or appropriate in the public interest and consistent with the protection of investors and the purposes fairly intended by the policy and provisions of this subchapter. For purposes of this paragraph, a security issued or guaranteed by a bank shall not include any interest or participation in any collective trust fund maintained by a bank; and the term \"bank\" means any national bank, or banking institution organized under the laws of any State, territory, or the District of Columbia, the business of which is substantially confined to banking and is supervised by the State or territorial banking commission or similar official; except that in the case of a common trust fund or similar fund, or a collective trust fund, the term \"bank\" has the same meaning as in the Investment Company Act of 1940 [15 U.S.C. 80a–1 et seq.];"],[1,"(3) Any note, draft, bill of exchange, or banker's acceptance which arises out of a current transaction or the proceeds of which have been or are to be used for current transactions, and which has a maturity at the time of issuance of not exceeding nine months, exclusive of days of grace, or any renewal thereof the maturity of which is likewise limited;"],[1,"(4) Any security issued by a person organized and operated exclusively for religious, educational, benevolent, fraternal, charitable, or reformatory purposes and not for pecuniary profit, and no part of the net earnings of which inures to the benefit of any person, private stockholder, or individual, or any security of a fund that is excluded from the definition of an investment company under section 3(c)(10)(B) of the Investment Company Act of 1940 [15 U.S.C. 80a–3(c)(10)(B)];"],[1,"(5) Any security issued (A) by a savings and loan association, building and loan association, cooperative bank, homestead association, or similar institution, which is supervised and examined by State or Federal authority having supervision over any such institution; or (B) by (i) a farmer's cooperative organization exempt from tax under section 521 of title 26, (ii) a corporation described in section 501(c)(16) of title 26 and exempt from tax under section 501(a) of title 26, or (iii) a corporation described in section 501(c)(2) of title 26 which is exempt from tax under section 501(a) of title 26 and is organized for the exclusive purpose of holding title to property, collecting income therefrom, and turning over the entire amount thereof, less expenses, to an organization or corporation described in clause (i) or (ii);"],[1,"(6) Any interest in a railroad equipment trust. For purposes of this paragraph \"interest in a railroad equipment trust\" means any interest in an equipment trust, lease, conditional sales contract, or other similar arrangement entered into, issued, assumed, guaranteed by, or for the benefit of, a common carrier to finance the acquisition of rolling stock, including motive power;"],[1,"(7) Certificates issued by a receiver or by a trustee or debtor in possession in a case under title 11, with the approval of the court;"],[1,"(8) Any insurance or endowment policy or annuity contract or optional annuity contract, issued by a corporation subject to the supervision of the insurance commissioner, bank commissioner, or any agency or officer performing like functions, of any State or Territory of the United States or the District of Columbia;"],[1,"(9) Except with respect to a security exchanged in a case under title 11, any security exchanged by the issuer with its existing security holders exclusively where no commission or other remuneration is paid or given directly or indirectly for soliciting such exchange;"],[1,"(10) Except with respect to a security exchanged in a case under title 11, any security which is issued in exchange for one or more bona fide outstanding securities, claims or property interests, or partly in such exchange and partly for cash, where the terms and conditions of such issuance and exchange are approved, after a hearing upon the fairness of such terms and conditions at which all persons to whom it is proposed to issue securities in such exchange shall have the right to appear, by any court, or by any official or agency of the United States, or by any State or Territorial banking or insurance commission or other governmental authority expressly authorized by law to grant such approval;"],[1,"(11) Any security which is a part of an issue offered and sold only to persons resident within a single State or Territory, where the issuer of such security is a person resident and doing business within or, if a corporation, incorporated by and doing business within, such State or Territory."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77c?type=usc&year=mostrecent&link-type=html"},"head":"§77c. Classes of securities under this subchapter","tname":"Commerce and Trade","by":{"0":"20, 44","1":"4, 24, 42, 45, 24, 30, 30","2":"3, 4, 7, 16"}},{"t":"usc","label":"15 U.S.C. § 77d","url":"https://www.law.cornell.edu/uscode/text/15/77d","subs":["(a)","(a)(1)","(a)(3)(B)","(a)(2)"],"stext":{"head":"§77d. Exempted transactions","paras":[[0,"(a) In general"],[0,"The provisions of section 77e of this title shall not apply to—"],[1,"(1) transactions by any person other than an issuer, underwriter, or dealer."],[1,"(2) transactions by an issuer not involving any public offering."],[1,"(3) transactions by a dealer (including an underwriter no longer acting as an underwriter in respect of the security involved in such transaction), except—"],[2,"(A) transactions taking place prior to the expiration of forty days after the first date upon which the security was bona fide offered to the public by the issuer or by or through an underwriter,"],[2,"(B) transactions in a security as to which a registration statement has been filed taking place prior to the expiration of forty days after the effective date of such registration statement or prior to the expiration of forty days after the first date upon which the security was bona fide offered to the public by the issuer or by or through an underwriter after such effective date, whichever is later (excluding in the computation of such forty days any time during which a stop order issued under section 77h of this title is in effect as to the security), or such shorter period as the Commission may specify by rules and regulations or order, and"],[2,"(C) transactions as to securities constituting the whole or a part of an unsold allotment to or subscription by such dealer as a participant in the distribution of such securities by the issuer or by or through an underwriter."],[1,"With respect to transactions referred to in clause (B), if securities of the issuer have not previously been sold pursuant to an earlier effective registration statement the applicable period, instead of forty days, shall be ninety days, or such shorter period as the Commission may specify by rules and regulations or order."],[1,"(4) brokers' transactions executed upon customers' orders on any exchange or in the over-the-counter market but not the solicitation of such orders."],[1,"(5) transactions involving offers or sales by an issuer solely to one or more accredited investors, if the aggregate offering price of an issue of securities offered in reliance on this paragraph does not exceed the amount allowed under section 77c(b)(1) of this title, if there is no advertising or public solicitation in connection with the transaction by the issuer or anyone acting on the issuer's behalf, and if the issuer files such notice with the Commission as the Commission shall prescribe."],[1,"(6) transactions involving the offer or sale of securities by an issuer (including all entities controlled by or under common control with the issuer), provided that—"],[2,"(A) the aggregate amount sold to all investors by the issuer, including any amount sold in reliance on the exemption provided under this paragraph during the 12-month period preceding the date of such transaction, is not more than $1,000,000;"],[2,"(B) the aggregate amount sold to any investor by an issuer, including any amount sold in reliance on the exemption provided under this paragraph during the 12-month period preceding the date of such transaction, does not exceed—"],[3,"(i) the greater of $2,000 or 5 percent of the annual income or net worth of such investor, as applicable, if either the annual income or the net worth of the investor is less than $100,000; and"],[3,"(ii) 10 percent of the annual income or net worth of such investor, as applicable, not to exceed a maximum aggregate amount sold of $100,000, if either the annual income or net worth of the investor is equal to or more than $100,000;"],[2,"(C) the transaction is conducted through a broker or funding portal that complies with the requirements of section 77d–1(a) of this title; and"],[2,"(D) the issuer complies with the requirements of section 77d–1(b) of this title."],[1,"(7) transactions meeting the requirements of subsection (d)."],[0,"(b) Offers and sales exempt under 17 CFR 230.506"],[0,"Offers and sales exempt under section 230.506 of title 17, Code of Federal Regulations (as revised pursuant to section 201 of the Jumpstart Our Business Startups Act) shall not be deemed public offerings under the Federal securities laws as a result of general advertising or general solicitation."],[0,"(c) Securities offered and sold in compliance with Rule 506 of Regulation D"],[0,"(1) With respect to securities offered and sold in compliance with Rule 506 of Regulation D under this subchapter, no person who meets the conditions set forth in paragraph (2) shall be subject to registration as a broker or dealer pursuant to section 78o(a)(1) of this title,1 solely because—"],[1,"(A) that person maintains a platform or mechanism that permits the offer, sale, purchase, or negotiation of or with respect to securities, or permits general solicitations, general advertisements, or similar or related activities by issuers of such securities, whether online, in person, or through any other means;"],[1,"(B) that person or any person associated with that person co-invests in such securities; or"],[1,"(C) that person or any person associated with that person provides ancillary services with respect to such securities."],[0,"(2) The exemption provided in paragraph (1) shall apply to any person described in such paragraph if—"],[1,"(A) such person and each person associated with that person receives no compensation in connection with the purchase or sale of such security;"],[1,"(B) such person and each person associated with that person does not have possession of customer funds or securities in connection with the purchase or sale of such security; and"],[1,"(C) such person is not subject to a statutory disqualification as defined in section 78c(a)(39) of this title 1 and does not have any person associated with that person subject to such a statutory disqualification."],[0,"(3) For the purposes of this subsection, the term \"ancillary services\" means—"],[1,"(A) the provision of due diligence services, in connection with the offer, sale, purchase, or negotiation of such security, so long as such services do not include, for separate compensation, investment advice or recommendations to issuers or investors; and"],[1,"(B) the provision of standardized documents to the issuers and investors, so long as such person or entity does not negotiate the terms of the issuance for and on behalf of third parties and issuers are not required to use the standardized documents as a condition of using the service."],[0,"(d) Certain accredited investor transactions"],[0,"The transactions referred to in subsection (a)(7) are transactions meeting the following requirements:"],[1,"(1) Accredited investor requirement.—Each purchaser is an accredited investor, as that term is defined in section 230.501(a) of title 17, Code of Federal Regulations (or any successor regulation)."],[1,"(2) Prohibition on general solicitation or advertising.—Neither the seller, nor any person acting on the seller's behalf, offers or sells securities by any form of general solicitation or general advertising."],[1,"(3) Information requirement.—In the case of a transaction involving the securities of an issuer that is neither subject to section 78m or 78o(d) of this title, nor exempt from reporting pursuant to section 240.12g3–2(b) of title 17, Code of Federal Regulations, nor a foreign government (as defined in section 230.405 of title 17, Code of Federal Regulations) eligible to register securities under Schedule B, the seller and a prospective purchaser designated by the seller obtain from the issuer, upon request of the seller, and the seller in all cases makes available to a prospective purchaser, the following information (which shall be reasonably current in relation to the date of resale under this section):"],[2,"(A) The exact name of the issuer and the issuer's predecessor (if any)."],[2,"(B) The address of the issuer's principal executive offices."],[2,"(C) The exact title and class of the security."],[2,"(D) The par or stated value of the security."],[2,"(E) The number of shares or total amount of the securities outstanding as of the end of the issuer's most recent fiscal year."],[2,"(F) The name and address of the transfer agent, corporate secretary, or other person responsible for transferring shares and stock certificates."],[2,"(G) A statement of the nature of the business of the issuer and the products and services it offers, which shall be presumed reasonably current if the statement is as of 12 months before the transaction date."],[2,"(H) The names of the officers and directors of the issuer."],[2,"(I) The names of any persons registered as a broker, dealer, or agent that shall be paid or given, directly or indirectly, any commission or remuneration for such person's participation in the offer or sale of the securities."],[2,"(J) The issuer's most recent balance sheet and profit and loss statement and similar financial statements, which shall—"],[3,"(i) be for such part of the 2 preceding fiscal years as the issuer has been in operation;"],[3,"(ii) be prepared in accordance with generally accepted accounting principles or, in the case of a foreign private issuer, be prepared in accordance with generally accepted accounting principles or the International Financial Reporting Standards issued by the International Accounting Standards Board;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77d?type=usc&year=mostrecent&link-type=html"},"op":1,"sum":"Recognizing as exempt certain securities “acquired directly . . . from the issuer . . . in a transaction or chain of transactions not involving any public offering”.","sumSrc":"opinion","head":"§77d. Exempted transactions","tname":"Commerce and Trade","by":{"0":"37, 37, 37","1":"4, 5, 11, 12, 23, 24, 26, 42, 24, 5, 11, 26, 23","2":"3, 4, 7, 14, 14, 7"}},{"t":"usc","label":"15 U.S.C. § 77e","url":"https://www.law.cornell.edu/uscode/text/15/77e","subs":["(a)","(b)(1)","(a)(1)","(c)","(b)"],"stext":{"head":"§77e. Prohibitions relating to interstate commerce and the mails","paras":[[0,"(a) Sale or delivery after sale of unregistered securities"],[0,"Unless a registration statement is in effect as to a security, it shall be unlawful for any person, directly or indirectly—"],[1,"(1) to make use of any means or instruments of transportation or communication in interstate commerce or of the mails to sell such security through the use or medium of any prospectus or otherwise; or"],[1,"(2) to carry or cause to be carried through the mails or in interstate commerce, by any means or instruments of transportation, any such security for the purpose of sale or for delivery after sale."],[0,"(b) Necessity of prospectus meeting requirements of section 77j of this title"],[0,"It shall be unlawful for any person, directly or indirectly—"],[1,"(1) to make use of any means or instruments of transportation or communication in interstate commerce or of the mails to carry or transmit any prospectus relating to any security with respect to which a registration statement has been filed under this subchapter, unless such prospectus meets the requirements of section 77j of this title; or"],[1,"(2) to carry or cause to be carried through the mails or in interstate commerce any such security for the purpose of sale or for delivery after sale, unless accompanied or preceded by a prospectus that meets the requirements of subsection (a) of section 77j of this title."],[0,"(c) Necessity of filing registration statement"],[0,"It shall be unlawful for any person, directly or indirectly, to make use of any means or instruments of transportation or communication in interstate commerce or of the mails to offer to sell or offer to buy through the use or medium of any prospectus or otherwise any security, unless a registration statement has been filed as to such security, or while the registration statement is the subject of a refusal order or stop order or (prior to the effective date of the registration statement) any public proceeding or examination under section 77h of this title."],[0,"(d) Limitation"],[0,"Notwithstanding any other provision of this section, an emerging growth company or any person authorized to act on behalf of an emerging growth company may engage in oral or written communications with potential investors that are qualified institutional buyers or institutions that are accredited investors, as such terms are respectively defined in section 230.144A and section 230.501(a) of title 17, Code of Federal Regulations, or any successor thereto, to determine whether such investors might have an interest in a contemplated securities offering, either prior to or following the date of filing of a registration statement with respect to such securities with the Commission, subject to the requirement of subsection (b)(2)."],[0,"(e) Security-based swaps"],[0,"Notwithstanding the provisions of section 77c or 77d of this title, unless a registration statement meeting the requirements of section 77j(a) of this title is in effect as to a security-based swap, it shall be unlawful for any person, directly or indirectly, to make use of any means or instruments of transportation or communication in interstate commerce or of the mails to offer to sell, offer to buy or purchase or sell a security-based swap to any person who is not an eligible contract participant as defined in section 1a(18) of title 7."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77e?type=usc&year=mostrecent&link-type=html"},"head":"§77e. Prohibitions relating to interstate commerce and the mails","tname":"Commerce and Trade","by":{"0":"37, 37, 37","1":"4, 23, 24, 30, 49, 4, 5, 23, 4","2":"3, 7, 4, 5, 12, 7"}},{"t":"usc","label":"15 U.S.C. § 77f","url":"https://www.law.cornell.edu/uscode/text/15/77f","subs":["(a)","(b)(1)"],"stext":{"head":"§77f. Registration of securities","paras":[[0,"(a) Method of registration"],[0,"Any security may be registered with the Commission under the terms and conditions hereinafter provided, by filing a registration statement in triplicate, at least one of which shall be signed by each issuer, its principal executive officer or officers, its principal financial officer, its comptroller or principal accounting officer, and the majority of its board of directors or persons performing similar functions (or, if there is no board of directors or persons performing similar functions, by the majority of the persons or board having the power of management of the issuer), and in case the issuer is a foreign or Territorial person by its duly authorized representative in the United States; except that when such registration statement relates to a security issued by a foreign government, or political subdivision thereof, it need be signed only by the underwriter of such security. Signatures of all such persons when written on the said registration statements shall be presumed to have been so written by authority of the person whose signature is so affixed and the burden of proof, in the event such authority shall be denied, shall be upon the party denying the same. The affixing of any signature without the authority of the purported signer shall constitute a violation of this subchapter. A registration statement shall be deemed effective only as to the securities specified therein as proposed to be offered."],[0,"(b) Registration fee"],[0,"(1) Fee payment required"],[1,"At the time of filing a registration statement, the applicant shall pay to the Commission a fee at a rate that shall be equal to $92 1 per $1,000,000 of the maximum aggregate price at which such securities are proposed to be offered, except that during fiscal year 2003 and any succeeding fiscal year such fee shall be adjusted pursuant to paragraph (2)."],[0,"(2) Annual adjustment"],[1,"For each fiscal year, the Commission shall by order adjust the rate required by paragraph (1) for such fiscal year to a rate that, when applied to the baseline estimate of the aggregate maximum offering prices for such fiscal year, is reasonably likely to produce aggregate fee collections under this subsection that are equal to the target fee collection amount for such fiscal year."],[0,"(3) Pro rata application"],[1,"The rates per $1,000,000 required by this subsection shall be applied pro rata to amounts and balances of less than $1,000,000."],[0,"(4) Review and effective date"],[1,"In exercising its authority under this subsection, the Commission shall not be required to comply with the provisions of section 553 of title 5. An adjusted rate prescribed under paragraph (2) and published under paragraph (5) shall not be subject to judicial review. An adjusted rate prescribed under paragraph (2) shall take effect on the first day of the fiscal year to which such rate applies."],[0,"(5) Publication"],[1,"The Commission shall publish in the Federal Register notices of the rate applicable under this subsection and under sections 78m(e) and 78n(g) 2 of this title for each fiscal year not later than August 31 of the fiscal year preceding the fiscal year to which such rate applies, together with any estimates or projections on which such rate is based."],[0,"(6) Definitions"],[1,"For purposes of this subsection:"],[0,"(A) Target fee collection amount"],[2,"The target fee collection amount for each fiscal year is determined according to the following table:"],[0,"(B) Baseline estimate of the aggregate maximum offering prices"],[2,"The baseline estimate of the aggregate maximum offering prices for any fiscal year is the baseline estimate of the aggregate maximum offering price at which securities are proposed to be offered pursuant to registration statements filed with the Commission during such fiscal year as determined by the Commission, after consultation with the Congressional Budget Office and the Office of Management and Budget, using the methodology required for projections pursuant to section 907 of title 2."],[0,"(c) Time registration effective"],[0,"The filing with the Commission of a registration statement, or of an amendment to a registration statement, shall be deemed to have taken place upon the receipt thereof, but the filing of a registration statement shall not be deemed to have taken place unless it is accompanied by a United States postal money order or a certified bank check or cash for the amount of the fee required under subsection (b)."],[0,"(d) Information available to public"],[0,"The information contained in or filed with any registration statement shall be made available to the public under such regulations as the Commission may prescribe, and copies thereof, photostatic or otherwise, shall be furnished to every applicant at such reasonable charge as the Commission may prescribe."],[0,"(e) Emerging growth companies"],[0,"(1) In general"],[1,"Any emerging growth company, prior to its initial public offering date, may confidentially submit to the Commission a draft registration statement, for confidential nonpublic review by the staff of the Commission prior to public filing, provided that the initial confidential submission and all amendments thereto shall be publicly filed with the Commission not later than 15 days before the date on which the issuer conducts a road show, as such term is defined in section 230.433(h)(4) of title 17, Code of Federal Regulations, or any successor thereto. An issuer that was an emerging growth company at the time it submitted a confidential registration statement or, in lieu thereof, a publicly filed registration statement for review under this subsection but ceases to be an emerging growth company thereafter shall continue to be treated as an emerging market growth company for the purposes of this subsection through the earlier of the date on which the issuer consummates its initial public offering pursuant to such registrations statement or the end of the 1-year period beginning on the date the company ceases to be an emerging growth company."],[0,"(2) Confidentiality"],[1,"Notwithstanding any other provision of this subchapter, the Commission shall not be compelled to disclose any information provided to or obtained by the Commission pursuant to this subsection. For purposes of section 552 of title 5, this subsection shall be considered a statute described in subsection (b)(3)(B) of such section 552. Information described in or obtained pursuant to this subsection shall be deemed to constitute confidential information for purposes of section 78x(b)(2) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77f?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§77f. Registration of securities","tname":"Commerce and Trade","by":{"0":"37, 37, 37","1":"4, 8, 30, 8, 22, 30, 31","2":"3, 7, 4, 5, 10, 4, 10"}},{"t":"usc","label":"15 U.S.C. § 77g","url":"https://www.law.cornell.edu/uscode/text/15/77g","subs":["(a)(1)"],"stext":{"head":"§77g. Information required in registration statement","paras":[[0,"(a) Information required in registration statement"],[0,"(1) In general"],[1,"The registration statement, when relating to a security other than a security issued by a foreign government, or political subdivision thereof, shall contain the information, and be accompanied by the documents, specified in Schedule A of section 77aa of this title, and when relating to a security issued by a foreign government, or political subdivision thereof, shall contain the information, and be accompanied by the documents, specified in Schedule B of section 77aa of this title; except that the Commission may by rules or regulations provide that any such information or document need not be included in respect of any class of issuers or securities if it finds that the requirement of such information or document is inapplicable to such class and that disclosure fully adequate for the protection of investors is otherwise required to be included within the registration statement. If any accountant, engineer, or appraiser, or any person whose profession gives authority to a statement made by him, is named as having prepared or certified any part of the registration statement, or is named as having prepared or certified a report or valuation for use in connection with the registration statement, the written consent of such person shall be filed with the registration statement. If any such person is named as having prepared or certified a report or valuation (other than a public official document or statement) which is used in connection with the registration statement, but is not named as having prepared or certified such report or valuation for use in connection with the registration statement, the written consent of such person shall be filed with the registration statement unless the Commission dispenses with such filing as impracticable or as involving undue hardship on the person filing the registration statement. Any such registration statement shall contain such other information, and be accompanied by such other documents, as the Commission may by rules or regulations require as being necessary or appropriate in the public interest or for the protection of investors."],[0,"(2) Treatment of emerging growth companies"],[1,"An emerging growth company—"],[2,"(A) need not present more than 2 years of audited financial statements in order for the registration statement of such emerging growth company with respect to an initial public offering of its common equity securities to be effective, and in any other registration statement to be filed with the Commission, an emerging growth company need not present selected financial data in accordance with section 229.301 of title 17, Code of Federal Regulations, for any period prior to the earliest audited period presented in connection with its initial public offering; and"],[2,"(B) may not be required to comply with any new or revised financial accounting standard until such date that a company that is not an issuer (as defined under section 7201 of this title) is required to comply with such new or revised accounting standard, if such standard applies to companies that are not issuers."],[0,"(b) Registration statement for blank check companies"],[0,"(1) The Commission shall prescribe special rules with respect to registration statements filed by any issuer that is a blank check company. Such rules may, as the Commission determines necessary or appropriate in the public interest or for the protection of investors—"],[1,"(A) require such issuers to provide timely disclosure, prior to or after such statement becomes effective under section 77h of this title, of (i) information regarding the company to be acquired and the specific application of the proceeds of the offering, or (ii) additional information necessary to prevent such statement from being misleading;"],[1,"(B) place limitations on the use of such proceeds and the distribution of securities by such issuer until the disclosures required under subparagraph (A) have been made; and"],[1,"(C) provide a right of rescission to shareholders of such securities."],[0,"(2) The Commission may, as it determines consistent with the public interest and the protection of investors, by rule or order exempt any issuer or class of issuers from the rules prescribed under paragraph (1)."],[0,"(3) For purposes of paragraph (1) of this subsection, the term \"blank check company\" means any development stage company that is issuing a penny stock (within the meaning of section 78c(a)(51) of this title) and that—"],[1,"(A) has no specific business plan or purpose; or"],[1,"(B) has indicated that its business plan is to merge with an unidentified company or companies."],[0,"(c) Disclosure requirements"],[0,"(1) In general"],[1,"The Commission shall adopt regulations under this subsection requiring each issuer of an asset-backed security to disclose, for each tranche or class of security, information regarding the assets backing that security."],[0,"(2) Content of regulations"],[1,"In adopting regulations under this subsection, the Commission shall—"],[2,"(A) set standards for the format of the data provided by issuers of an asset-backed security, which shall, to the extent feasible, facilitate comparison of such data across securities in similar types of asset classes; and"],[2,"(B) require issuers of asset-backed securities, at a minimum, to disclose asset-level or loan-level data, if such data are necessary for investors to independently perform due diligence, including—"],[3,"(i) data having unique identifiers relating to loan brokers or originators;"],[3,"(ii) the nature and extent of the compensation of the broker or originator of the assets backing the security; and"],[3,"(iii) the amount of risk retention by the originator and the securitizer of such assets."],[0,"(3) Data standards for asset-backed securities disclosures"],[0,"(A) Requirement"],[2,"The Commission shall, by rule, adopt data standards for all disclosures required under this subsection."],[0,"(B) Consistency"],[2,"The data standards required under subparagraph (A) shall incorporate, and ensure compatibility with (to the extent feasible), all applicable data standards established in the rules promulgated under section 5334 of title 12, including, to the extent practicable, by having the characteristics described in clauses (i) through (vi) of subsection (c)(1)(B) of such section 5334."],[0,"(d) Registration statement for asset-backed securities"],[0,"Not later than 180 days after July 21, 2010, the Commission shall issue rules relating to the registration statement required to be filed by any issuer of an asset-backed security (as that term is defined in section 78c(a)(77) 1 of this title) that require any issuer of an asset-backed security—"],[1,"(1) to perform a review of the assets underlying the asset-backed security; and"],[1,"(2) to disclose the nature of the review under paragraph (1)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77g?type=usc&year=mostrecent&link-type=html"},"head":"§77g. Information required in registration statement","tname":"Commerce and Trade","by":{"0":"37","1":"4, 25","2":"3"}},{"t":"usc","label":"15 U.S.C. § 77j","url":"https://www.law.cornell.edu/uscode/text/15/77j","subs":["(a)(1)","(a)(3)","(f)"],"stext":{"head":"§77j. Information required in prospectus","paras":[[0,"(a) Information in registration statement; documents not required"],[0,"Except to the extent otherwise permitted or required pursuant to this subsection or subsections (c), (d), or (e)—"],[1,"(1) a prospectus relating to a security other than a security issued by a foreign government or political subdivision thereof, shall contain the information contained in the registration statement, but it need not include the documents referred to in paragraphs (28) to (32), inclusive, of schedule A of section 77aa of this title;"],[1,"(2) a prospectus relating to a security issued by a foreign government or political subdivision thereof shall contain the information contained in the registration statement, but it need not include the documents referred to in paragraphs (13) and (14) of schedule B of section 77aa of this title;"],[1,"(3) notwithstanding the provisions of paragraphs (1) and (2) of this subsection when a prospectus is used more than nine months after the effective date of the registration statement, the information contained therein shall be as of a date not more than sixteen months prior to such use, so far as such information is known to the user of such prospectus or can be furnished by such user without unreasonable effort or expense;"],[1,"(4) there may be omitted from any prospectus any of the information required under this subsection which the Commission may by rules or regulations designate as not being necessary or appropriate in the public interest or for the protection of investors."],[0,"(b) Summarizations and omissions allowed by rules and regulations"],[0,"In addition to the prospectus permitted or required in subsection (a), the Commission shall by rules or regulations deemed necessary or appropriate in the public interest or for the protection of investors permit the use of a prospectus for the purposes of subsection (b)(1) of section 77e of this title which omits in part or summarizes information in the prospectus specified in subsection (a). A prospectus permitted under this subsection shall, except to the extent the Commission by rules or regulations deemed necessary or appropriate in the public interest or for the protection of investors otherwise provides, be filed as part of the registration statement but shall not be deemed a part of such registration statement for the purposes of section 77k of this title. The Commission may at any time issue an order preventing or suspending the use of a prospectus permitted under this subsection, if it has reason to believe that such prospectus has not been filed (if required to be filed as part of the registration statement) or includes any untrue statement of a material fact or omits to state any material fact required to be stated therein or necessary to make the statements therein, in the light of the circumstances under which such prospectus is or is to be used, not misleading. Upon issuance of an order under this subsection, the Commission shall give notice of the issuance of such order and opportunity for hearing by personal service or the sending of confirmed telegraphic notice. The Commission shall vacate or modify the order at any time for good cause or if such prospectus has been filed or amended in accordance with such order."],[0,"(c) Additional information required by rules and regulations"],[0,"Any prospectus shall contain such other information as the Commission may by rules or regulations require as being necessary or appropriate in the public interest or for the protection of investors."],[0,"(d) Classification of prospectuses"],[0,"In the exercise of its powers under subsections (a), (b), or (c), the Commission shall have authority to classify prospectuses according to the nature and circumstances of their use or the nature of the security, issue, issuer, or otherwise, and, by rules and regulations and subject to such terms and conditions as it shall specify therein, to prescribe as to each class the form and contents which it may find appropriate and consistent with the public interest and the protection of investors."],[0,"(e) Information in conspicuous part of prospectus"],[0,"The statements or information required to be included in a prospectus by or under authority of subsections (a), (b), (c), or (d), when written, shall be placed in a conspicuous part of the prospectus and, except as otherwise permitted by rules or regulations, in type as large as that used generally in the body of the prospectus."],[0,"(f) Prospectus consisting of radio or television broadcast"],[0,"In any case where a prospectus consists of a radio or television broadcast, copies thereof shall be filed with the Commission under such rules and regulations as it shall prescribe. The Commission may by rules and regulations require the filing with it of forms and prospectuses used in connection with the offer or sale of securities registered under this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77j?type=usc&year=mostrecent&link-type=html"},"head":"§77j. Information required in prospectus","tname":"Commerce and Trade","by":{"0":"37, 37, 37, 37","1":"24, 29, 43, 44, 5, 44, 24, 29","2":"3, 6"}},{"t":"usc","label":"15 U.S.C. § 77k","url":"https://www.law.cornell.edu/uscode/text/15/77k","subs":["(a)","(e)","(g)","(b)"],"stext":{"head":"§77k. Civil liabilities on account of false registration statement","paras":[[0,"(a) Persons possessing cause of action; persons liable"],[0,"In case any part of the registration statement, when such part became effective, contained an untrue statement of a material fact or omitted to state a material fact required to be stated therein or necessary to make the statements therein not misleading, any person acquiring such security (unless it is proved that at the time of such acquisition he knew of such untruth or omission) may, either at law or in equity, in any court of competent jurisdiction, sue—"],[1,"(1) every person who signed the registration statement;"],[1,"(2) every person who was a director of (or person performing similar functions) or partner in the issuer at the time of the filing of the part of the registration statement with respect to which his liability is asserted;"],[1,"(3) every person who, with his consent, is named in the registration statement as being or about to become a director, person performing similar functions, or partner;"],[1,"(4) every accountant, engineer, or appraiser, or any person whose profession gives authority to a statement made by him, who has with his consent been named as having prepared or certified any part of the registration statement, or as having prepared or certified any report or valuation which is used in connection with the registration statement, with respect to the statement in such registration statement, report, or valuation, which purports to have been prepared or certified by him;"],[1,"(5) every underwriter with respect to such security."],[0,"If such person acquired the security after the issuer has made generally available to its security holders an earning statement covering a period of at least twelve months beginning after the effective date of the registration statement, then the right of recovery under this subsection shall be conditioned on proof that such person acquired the security relying upon such untrue statement in the registration statement or relying upon the registration statement and not knowing of such omission, but such reliance may be established without proof of the reading of the registration statement by such person."],[0,"(b) Persons exempt from liability upon proof of issues"],[0,"Notwithstanding the provisions of subsection (a) no person, other than the issuer, shall be liable as provided therein who shall sustain the burden of proof—"],[1,"(1) that before the effective date of the part of the registration statement with respect to which his liability is asserted (A) he had resigned from or had taken such steps as are permitted by law to resign from, or ceased or refused to act in, every office, capacity, or relationship in which he was described in the registration statement as acting or agreeing to act, and (B) he had advised the Commission and the issuer in writing that he had taken such action and that he would not be responsible for such part of the registration statement; or"],[1,"(2) that if such part of the registration statement became effective without his knowledge, upon becoming aware of such fact he forthwith acted and advised the Commission, in accordance with paragraph (1) of this subsection, and, in addition, gave reasonable public notice that such part of the registration statement had become effective without his knowledge; or"],[1,"(3) that (A) as regards any part of the registration statement not purporting to be made on the authority of an expert, and not purporting to be a copy of or extract from a report or valuation of an expert, and not purporting to be made on the authority of a public official document or statement, he had, after reasonable investigation, reasonable ground to believe and did believe, at the time such part of the registration statement became effective, that the statements therein were true and that there was no omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading; and (B) as regards any part of the registration statement purporting to be made upon his authority as an expert or purporting to be a copy of or extract from a report or valuation of himself as an expert, (i) he had, after reasonable investigation, reasonable ground to believe and did believe, at the time such part of the registration statement became effective, that the statements therein were true and that there was no omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading, or (ii) such part of the registration statement did not fairly represent his statement as an expert or was not a fair copy of or extract from his report or valuation as an expert; and (C) as regards any part of the registration statement purporting to be made on the authority of an expert (other than himself) or purporting to be a copy of or extract from a report or valuation of an expert (other than himself), he had no reasonable ground to believe and did not believe, at the time such part of the registration statement became effective, that the statements therein were untrue or that there was an omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading, or that such part of the registration statement did not fairly represent the statement of the expert or was not a fair copy of or extract from the report or valuation of the expert; and (D) as regards any part of the registration statement purporting to be a statement made by an official person or purporting to be a copy of or extract from a public official document, he had no reasonable ground to believe and did not believe, at the time such part of the registration statement became effective, that the statements therein were untrue, or that there was an omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading, or that such part of the registration statement did not fairly represent the statement made by the official person or was not a fair copy of or extract from the public official document."],[0,"(c) Standard of reasonableness"],[0,"In determining, for the purpose of paragraph (3) of subsection (b) of this section, what constitutes reasonable investigation and reasonable ground for belief, the standard of reasonableness shall be that required of a prudent man in the management of his own property."],[0,"(d) Effective date of registration statement with regard to underwriters"],[0,"If any person becomes an underwriter with respect to the security after the part of the registration statement with respect to which his liability is asserted has become effective, then for the purposes of paragraph (3) of subsection (b) of this section such part of the registration statement shall be considered as having become effective with respect to such person as of the time when he became an underwriter."],[0,"(e) Measure of damages; undertaking for payment of costs"],[0,"The suit authorized under subsection (a) may be to recover such damages as shall represent the difference between the amount paid for the security (not exceeding the price at which the security was offered to the public) and (1) the value thereof as of the time such suit was brought, or (2) the price at which such security shall have been disposed of in the market before suit, or (3) the price at which such security shall have been disposed of after suit but before judgment if such damages shall be less than the damages representing the difference between the amount paid for the security (not exceeding the price at which the security was offered to the public) and the value thereof as of the time such suit was brought: Provided, That if the defendant proves that any portion or all of such damages represents other than the depreciation in value of such security resulting from such part of the registration statement, with respect to which his liability is asserted, not being true or omitting to state a material fact required to be stated therein or necessary to make the statements therein not misleading, such portion of or all such damages shall not be recoverable. In no event shall any underwriter (unless such underwriter shall have knowingly received from the issuer for acting as an underwriter some benefit, directly or indirectly, in which all other underwriters similarly situated did not share in proportion to their respective interests in the underwriting) be liable in any suit or as a consequence of suits authorized under subsection (a) for damages in excess of the total price at which the securities underwritten by him and distributed to the public were offered to the public. In any suit under this or any other section of this subchapter the court may, in its discretion, require an undertaking for the payment of the costs of such suit, including reasonable attorney's fees, and if judgment shall be rendered against a party litigant, upon the motion of the other party litigant, such costs may be assessed in favor of such party litigant (whether or not such undertaking has been required) if the court believes the suit or the defense to have been without merit, in an amount sufficient to reimburse him for the reasonable expenses incurred by him, in connection with such suit, such costs to be taxed in the manner usually provided for taxing of costs in the court in which the suit was heard."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77k?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§77k. Civil liabilities on account of false registration statement","tname":"Commerce and Trade","by":{"0":"37, 37, 37, 37, 37","1":"6, 7, 9, 10, 12-15, 17-27, 29-31, 33-35, 37, 38, 40, 45, 46, 48, 1, 6, 15, 21, 33, 6, 33, 7, 31, 33, 31","2":"1, 3, 4, 5"}},{"t":"usc","label":"15 U.S.C. § 77l","url":"https://www.law.cornell.edu/uscode/text/15/77l","subs":["(a)","(a)(2)","(b)","(a)(1)"],"stext":{"head":"§77l. Civil liabilities arising in connection with prospectuses and communications","paras":[[0,"(a) In general"],[0,"Any person who—"],[1,"(1) offers or sells a security in violation of section 77e of this title, or"],[1,"(2) offers or sells a security (whether or not exempted by the provisions of section 77c of this title, other than paragraphs (2) and (14) of subsection (a) of said section), by the use of any means or instruments of transportation or communication in interstate commerce or of the mails, by means of a prospectus or oral communication, which includes an untrue statement of a material fact or omits to state a material fact necessary in order to make the statements, in the light of the circumstances under which they were made, not misleading (the purchaser not knowing of such untruth or omission), and who shall not sustain the burden of proof that he did not know, and in the exercise of reasonable care could not have known, of such untruth or omission,"],[0,"shall be liable, subject to subsection (b), to the person purchasing such security from him, who may sue either at law or in equity in any court of competent jurisdiction, to recover the consideration paid for such security with interest thereon, less the amount of any income received thereon, upon the tender of such security, or for damages if he no longer owns the security."],[0,"(b) Loss causation"],[0,"In an action described in subsection (a)(2), if the person who offered or sold such security proves that any portion or all of the amount recoverable under subsection (a)(2) represents other than the depreciation in value of the subject security resulting from such part of the prospectus or oral communication, with respect to which the liability of that person is asserted, not being true or omitting to state a material fact required to be stated therein or necessary to make the statement not misleading, then such portion or amount, as the case may be, shall not be recoverable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77l?type=usc&year=mostrecent&link-type=html"},"head":"§77l. Civil liabilities arising in connection with prospectuses and communications","tname":"Commerce and Trade","by":{"0":"37, 37, 37, 37","1":"6, 7, 16, 19, 39-45, 7, 41, 1, 7, 16, 40, 42, 44","2":"1, 12, 14, 11, 12"}},{"t":"usc","label":"15 U.S.C. § 77o","url":"https://www.law.cornell.edu/uscode/text/15/77o","subs":["(a)"],"by":{"0":"37"}},{"t":"usc","label":"15 U.S.C. § 77q","url":"https://www.law.cornell.edu/uscode/text/15/77q","subs":["(a)","(a)(1)"],"stext":{"head":"§77q. Fraudulent interstate transactions","paras":[[0,"(a) Use of interstate commerce for purpose of fraud or deceit"],[0,"It shall be unlawful for any person in the offer or sale of any securities (including security-based swaps) or any security-based swap agreement (as defined in section 78c(a)(78) 1 of this title) by the use of any means or instruments of transportation or communication in interstate commerce or by use of the mails, directly or indirectly—"],[1,"(1) to employ any device, scheme, or artifice to defraud, or"],[1,"(2) to obtain money or property by means of any untrue statement of a material fact or any omission to state a material fact necessary in order to make the statements made, in light of the circumstances under which they were made, not misleading; or"],[1,"(3) to engage in any transaction, practice, or course of business which operates or would operate as a fraud or deceit upon the purchaser."],[0,"(b) Use of interstate commerce for purpose of offering for sale"],[0,"It shall be unlawful for any person, by the use of any means or instruments of transportation or communication in interstate commerce or by the use of the mails, to publish, give publicity to, or circulate any notice, circular, advertisement, newspaper, article, letter, investment service, or communication which, though not purporting to offer a security for sale, describes such security for a consideration received or to be received, directly or indirectly, from an issuer, underwriter, or dealer, without fully disclosing the receipt, whether past or prospective, of such consideration and the amount thereof."],[0,"(c) Exemptions of section 77c not applicable to this section"],[0,"The exemptions provided in section 77c of this title shall not apply to the provisions of this section."],[0,"(d) Authority with respect to security-based swap agreements"],[0,"The authority of the Commission under this section with respect to security-based swap agreements (as defined in section 78c(a)(78) of this title) shall be subject to the restrictions and limitations of section 77b–1(b) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77q?type=usc&year=mostrecent&link-type=html"},"head":"§77q. Fraudulent interstate transactions","tname":"Commerce and Trade","by":{"0":"37, 37","1":"34, 3","2":"15"}},{"t":"usc","label":"15 U.S.C. § 77z-2","url":"https://www.law.cornell.edu/uscode/text/15/77z-2","by":{"0":"37"}},{"t":"usc","label":"15 U.S.C. § 78c","url":"https://www.law.cornell.edu/uscode/text/15/78c","by":{"0":"4"}},{"t":"usc","label":"15 U.S.C. § 78j","url":"https://www.law.cornell.edu/uscode/text/15/78j","subs":["(b)"],"stext":{"head":"§78j. Manipulative and deceptive devices","paras":[[0,"It shall be unlawful for any person, directly or indirectly, by the use of any means or instrumentality of interstate commerce or of the mails, or of any facility of any national securities exchange—"],[1,"(a)(1) To effect a short sale, or to use or employ any stop-loss order in connection with the purchase or sale, of any security other than a government security, in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Paragraph (1) of this subsection shall not apply to security futures products."],[1,"(b) To use or employ, in connection with the purchase or sale of any security registered on a national securities exchange or any security not so registered, or any securities-based swap agreement 1 any manipulative or deceptive device or contrivance in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(c)(1) To effect, accept, or facilitate a transaction involving the loan or borrowing of securities in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Nothing in paragraph (1) may be construed to limit the authority of the appropriate Federal banking agency (as defined in section 1813(q) of title 12), the National Credit Union Administration, or any other Federal department or agency having a responsibility under Federal law to prescribe rules or regulations restricting transactions involving the loan or borrowing of securities in order to protect the safety and soundness of a financial institution or to protect the financial system from systemic risk."],[0,"Rules promulgated under subsection (b) that prohibit fraud, manipulation, or insider trading (but not rules imposing or specifying reporting or recordkeeping requirements, procedures, or standards as prophylactic measures against fraud, manipulation, or insider trading), and judicial precedents decided under subsection (b) and rules promulgated thereunder that prohibit fraud, manipulation, or insider trading, shall apply to security-based swap agreements to the same extent as they apply to securities. Judicial precedents decided under section 77q(a) of this title and sections 78i, 78o, 78p, 78t, and 78u–1 of this title, and judicial precedents decided under applicable rules promulgated under such sections, shall apply to security-based swap agreements to the same extent as they apply to securities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78j?type=usc&year=mostrecent&link-type=html"},"head":"§78j. Manipulative and deceptive devices","tname":"Commerce and Trade","by":{"0":"16","1":"18, 33, 34, 35","2":"15"}},{"t":"usc","label":"15 U.S.C. § 78l","url":"https://www.law.cornell.edu/uscode/text/15/78l","subs":["(b)","(c)","(g)"],"stext":{"head":"§78l. Registration requirements for securities","paras":[[0,"(a) General requirement of registration"],[0,"It shall be unlawful for any member, broker, or dealer to effect any transaction in any security (other than an exempted security) on a national securities exchange unless a registration is effective as to such security for such exchange in accordance with the provisions of this chapter and the rules and regulations thereunder. The provisions of this subsection shall not apply in respect of a security futures product traded on a national securities exchange."],[0,"(b) Procedure for registration; information"],[0,"A security may be registered on a national securities exchange by the issuer filing an application with the exchange (and filing with the Commission such duplicate originals thereof as the Commission may require), which application shall contain—"],[1,"(1) Such information, in such detail, as to the issuer and any person directly or indirectly controlling or controlled by, or under direct or indirect common control with, the issuer, and any guarantor of the security as to principal or interest or both, as the Commission may by rules and regulations require, as necessary or appropriate in the public interest or for the protection of investors, in respect of the following:"],[2,"(A) the organization, financial structure, and nature of the business;"],[2,"(B) the terms, position, rights, and privileges of the different classes of securities outstanding;"],[2,"(C) the terms on which their securities are to be, and during the preceding three years have been, offered to the public or otherwise;"],[2,"(D) the directors, officers, and underwriters, and each security holder of record holding more than 10 per centum of any class of any equity security of the issuer (other than an exempted security), their remuneration and their interests in the securities of, and their material contracts with, the issuer and any person directly or indirectly controlling or controlled by, or under direct or indirect common control with, the issuer;"],[2,"(E) remuneration to others than directors and officers exceeding $20,000 per annum;"],[2,"(F) bonus and profit-sharing arrangements;"],[2,"(G) management and service contracts;"],[2,"(H) options existing or to be created in respect of their securities;"],[2,"(I) material contracts, not made in the ordinary course of business, which are to be executed in whole or in part at or after the filing of the application or which were made not more than two years before such filing, and every material patent or contract for a material patent right shall be deemed a material contract;"],[2,"(J) balance sheets for not more than the three preceding fiscal years, certified if required by the rules and regulations of the Commission by a registered public accounting firm;"],[2,"(K) profit and loss statements for not more than the three preceding fiscal years, certified if required by the rules and regulations of the Commission by a registered public accounting firm; and"],[2,"(L) any further financial statements which the Commission may deem necessary or appropriate for the protection of investors."],[1,"(2) Such copies of articles of incorporation, bylaws, trust indentures, or corresponding documents by whatever name known, underwriting arrangements, and other similar documents of, and voting trust agreements with respect to, the issuer and any person directly or indirectly controlling or controlled by, or under direct or indirect common control with, the issuer as the Commission may require as necessary or appropriate for the proper protection of investors and to insure fair dealing in the security."],[1,"(3) Such copies of material contracts, referred to in paragraph (1)(I) above, as the Commission may require as necessary or appropriate for the proper protection of investors and to insure fair dealing in the security."],[0,"(c) Additional or alternative information"],[0,"If in the judgment of the Commission any information required under subsection (b) is inapplicable to any specified class or classes of issuers, the Commission shall require in lieu thereof the submission of such other information of comparable character as it may deem applicable to such class of issuers."],[0,"(d) Effective date of registration; withdrawal of registration"],[0,"If the exchange authorities certify to the Commission that the security has been approved by the exchange for listing and registration, the registration shall become effective thirty days after the receipt of such certification by the Commission or within such shorter period of time as the Commission may determine. A security registered with a national securities exchange may be withdrawn or stricken from listing and registration in accordance with the rules of the exchange and, upon such terms as the Commission may deem necessary to impose for the protection of investors, upon application by the issuer or the exchange to the Commission; whereupon the issuer shall be relieved from further compliance with the provisions of this section and section 78m of this title and any rules or regulations under such sections as to the securities so withdrawn or stricken. An unissued security may be registered only in accordance with such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[0,"(e) Exemption from provisions of section for period ending not later than July 1, 1935"],[0,"Notwithstanding the foregoing provisions of this section, the Commission may by such rules and regulations as it deems necessary or appropriate in the public interest or for the protection of investors, permit securities listed on any exchange at the time the registration of such exchange as a national securities exchange becomes effective, to be registered for a period ending not later than July 1, 1935, without complying with the provisions of this section."],[0,"(f) Unlisted trading privileges for security originally listed on another national exchange"],[0,"(1)(A) Notwithstanding the preceding subsections of this section, any national securities exchange, in accordance with the requirements of this subsection and the rules hereunder, may extend unlisted trading privileges to—"],[1,"(i) any security that is listed and registered on a national securities exchange, subject to subparagraph (B); and"],[1,"(ii) any security that is otherwise registered pursuant to this section, or that would be required to be so registered except for the exemption from registration provided in subparagraph (B) or (G) of subsection (g)(2), subject to subparagraph (E) of this paragraph."],[0,"(B) A national securities exchange may not extend unlisted trading privileges to a security described in subparagraph (A)(i) during such interval, if any, after the commencement of an initial public offering of such security, as is or may be required pursuant to subparagraph (C)."],[0,"(C) Not later than 180 days after October 22, 1994, the Commission shall prescribe, by rule or regulation, the duration of the interval referred to in subparagraph (B), if any, as the Commission determines to be necessary or appropriate for the maintenance of fair and orderly markets, the protection of investors and the public interest, or otherwise in furtherance of the purposes of this chapter. Until the earlier of the effective date of such rule or regulation or 240 days after October 22, 1994, such interval shall begin at the opening of trading on the day on which such security commences trading on the national securities exchange with which such security is registered and end at the conclusion of the next day of trading."],[0,"(D) The Commission may prescribe, by rule or regulation such additional procedures or requirements for extending unlisted trading privileges to any security as the Commission deems necessary or appropriate for the maintenance of fair and orderly markets, the protection of investors and the public interest, or otherwise in furtherance of the purposes of this chapter."],[0,"(E) No extension of unlisted trading privileges to securities described in subparagraph (A)(ii) may occur except pursuant to a rule, regulation, or order of the Commission approving such extension or extensions. In promulgating such rule or regulation or in issuing such order, the Commission—"],[1,"(i) shall find that such extension or extensions of unlisted trading privileges is consistent with the maintenance of fair and orderly markets, the protection of investors and the public interest, and otherwise in furtherance of the purposes of this chapter;"],[1,"(ii) shall take account of the public trading activity in such securities, the character of such trading, the impact of such extension on the existing markets for such securities, and the desirability of removing impediments to and the progress that has been made toward the development of a national market system; and"],[1,"(iii) shall not permit a national securities exchange to extend unlisted trading privileges to such securities if any rule of such national securities exchange would unreasonably impair the ability of a dealer to solicit or effect transactions in such securities for its own account, or would unreasonably restrict competition among dealers in such securities or between such dealers acting in the capacity of market makers who are specialists and such dealers who are not specialists."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78l?type=usc&year=mostrecent&link-type=html"},"head":"§78l. Registration requirements for securities","tname":"Commerce and Trade","by":{"0":"16, 29, 16, 25","2":"16"}},{"t":"usc","label":"15 U.S.C. § 78m","url":"https://www.law.cornell.edu/uscode/text/15/78m","subs":["(c)"],"stext":{"head":"§78m. Periodical and other reports","paras":[[0,"(a) Reports by issuer of security; contents"],[0,"Every issuer of a security registered pursuant to section 78l of this title shall file with the Commission, in accordance with such rules and regulations as the Commission may prescribe as necessary or appropriate for the proper protection of investors and to insure fair dealing in the security—"],[1,"(1) such information and documents (and such copies thereof) as the Commission shall require to keep reasonably current the information and documents required to be included in or filed with an application or registration statement filed pursuant to section 78l of this title, except that the Commission may not require the filing of any material contract wholly executed before July 1, 1962."],[1,"(2) such annual reports (and such copies thereof), certified if required by the rules and regulations of the Commission by independent public accountants, and such quarterly reports (and such copies thereof), as the Commission may prescribe."],[0,"Every issuer of a security registered on a national securities exchange shall also file a duplicate original of such information, documents, and reports with the exchange. In any registration statement, periodic report, or other reports to be filed with the Commission, an emerging growth company need not present selected financial data in accordance with section 229.301 of title 17, Code of Federal Regulations, for any period prior to the earliest audited period presented in connection with its first registration statement that became effective under this chapter or the Securities Act of 1933 [15 U.S.C. 77a et seq.] and, with respect to any such statement or reports, an emerging growth company may not be required to comply with any new or revised financial accounting standard until such date that a company that is not an issuer (as defined under section 7201 of this title) is required to comply with such new or revised accounting standard, if such standard applies to companies that are not issuers."],[0,"(b) Form of report; books, records, and internal accounting; directives"],[0,"(1) The Commission may prescribe, in regard to reports made pursuant to this chapter, the form or forms in which the required information shall be set forth, the items or details to be shown in the balance sheet and the earnings statement, and the methods to be followed in the preparation of reports, in the appraisal or valuation of assets and liabilities, in the determination of depreciation and depletion, in the differentiation of recurring and nonrecurring income, in the differentiation of investment and operating income, and in the preparation, where the Commission deems it necessary or desirable, of separate and/or consolidated balance sheets or income accounts of any person directly or indirectly controlling or controlled by the issuer, or any person under direct or indirect common control with the issuer; but in the case of the reports of any person whose methods of accounting are prescribed under the provisions of any law of the United States, or any rule or regulation thereunder, the rules and regulations of the Commission with respect to reports shall not be inconsistent with the requirements imposed by such law or rule or regulation in respect of the same subject matter (except that such rules and regulations of the Commission may be inconsistent with such requirements to the extent that the Commission determines that the public interest or the protection of investors so requires)."],[0,"(2) Every issuer which has a class of securities registered pursuant to section 78l of this title and every issuer which is required to file reports pursuant to section 78o(d) of this title shall—"],[1,"(A) make and keep books, records, and accounts, which, in reasonable detail, accurately and fairly reflect the transactions and dispositions of the assets of the issuer;"],[1,"(B) devise and maintain a system of internal accounting controls sufficient to provide reasonable assurances that—"],[2,"(i) transactions are executed in accordance with management's general or specific authorization;"],[2,"(ii) transactions are recorded as necessary (I) to permit preparation of financial statements in conformity with generally accepted accounting principles or any other criteria applicable to such statements, and (II) to maintain accountability for assets;"],[2,"(iii) access to assets is permitted only in accordance with management's general or specific authorization; and"],[2,"(iv) the recorded accountability for assets is compared with the existing assets at reasonable intervals and appropriate action is taken with respect to any differences; and"],[1,"(C) notwithstanding any other provision of law, pay the allocable share of such issuer of a reasonable annual accounting support fee or fees, determined in accordance with section 7219 of this title."],[0,"(3)(A) With respect to matters concerning the national security of the United States, no duty or liability under paragraph (2) of this subsection shall be imposed upon any person acting in cooperation with the head of any Federal department or agency responsible for such matters if such act in cooperation with such head of a department or agency was done upon the specific, written directive of the head of such department or agency pursuant to Presidential authority to issue such directives. Each directive issued under this paragraph shall set forth the specific facts and circumstances with respect to which the provisions of this paragraph are to be invoked. Each such directive shall, unless renewed in writing, expire one year after the date of issuance."],[0,"(B) Each head of a Federal department or agency of the United States who issues a directive pursuant to this paragraph shall maintain a complete file of all such directives and shall, on October 1 of each year, transmit a summary of matters covered by such directives in force at any time during the previous year to the Permanent Select Committee on Intelligence of the House of Representatives and the Select Committee on Intelligence of the Senate."],[0,"(4) No criminal liability shall be imposed for failing to comply with the requirements of paragraph (2) of this subsection except as provided in paragraph (5) of this subsection."],[0,"(5) No person shall knowingly circumvent or knowingly fail to implement a system of internal accounting controls or knowingly falsify any book, record, or account described in paragraph (2)."],[0,"(6) Where an issuer which has a class of securities registered pursuant to section 78l of this title or an issuer which is required to file reports pursuant to section 78o(d) of this title holds 50 per centum or less of the voting power with respect to a domestic or foreign firm, the provisions of paragraph (2) require only that the issuer proceed in good faith to use its influence, to the extent reasonable under the issuer's circumstances, to cause such domestic or foreign firm to devise and maintain a system of internal accounting controls consistent with paragraph (2). Such circumstances include the relative degree of the issuer's ownership of the domestic or foreign firm and the laws and practices governing the business operations of the country in which such firm is located. An issuer which demonstrates good faith efforts to use such influence shall be conclusively presumed to have complied with the requirements of paragraph (2)."],[0,"(7) For the purpose of paragraph (2) of this subsection, the terms \"reasonable assurances\" and \"reasonable detail\" mean such level of detail and degree of assurance as would satisfy prudent officials in the conduct of their own affairs."],[0,"(c) Alternative reports"],[0,"If in the judgment of the Commission any report required under subsection (a) is inapplicable to any specified class or classes of issuers, the Commission shall require in lieu thereof the submission of such reports of comparable character as it may deem applicable to such class or classes of issuers."],[0,"(d) Reports by persons acquiring more than five per centum of certain classes of securities"],[0,"(1) Any person who, after acquiring directly or indirectly the beneficial ownership of any equity security of a class which is registered pursuant to section 78l of this title, or any equity security of an insurance company which would have been required to be so registered except for the exemption contained in section 78l(g)(2)(G) of this title, or any equity security issued by a closed-end investment company registered under the Investment Company Act of 1940 [15 U.S.C. 80a–1 et seq.] or any equity security issued by a Native Corporation pursuant to section 1629c(d)(6) of title 43, or otherwise becomes or is deemed to become a beneficial owner of any of the foregoing upon the purchase or sale of a security-based swap that the Commission may define by rule, and is directly or indirectly the beneficial owner of more than 5 per centum of such class shall, within ten days after such acquisition or within such shorter time as the Commission may establish by rule, file with the Commission, a statement containing such of the following information, and such additional information, as the Commission may by rules and regulations, prescribe as necessary or appropriate in the public interest or for the protection of investors—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78m?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§78m. Periodical and other reports","tname":"Commerce and Trade","by":{"0":"5, 29","2":"16"}},{"t":"usc","label":"15 U.S.C. § 78o","url":"https://www.law.cornell.edu/uscode/text/15/78o","subs":["(d)"],"by":{"0":"16, 25"}},{"t":"usc","label":"15 U.S.C. § 78p","url":"https://www.law.cornell.edu/uscode/text/15/78p","subs":["(a)","(a)(1)"],"by":{"0":"25, 16, 29","2":"16"}},{"t":"usc","label":"15 U.S.C. § 78u-4","url":"https://www.law.cornell.edu/uscode/text/15/78u-4","by":{"0":"6, 37"}},{"t":"law","label":"Other Statutes Dodd-Frank Wall Street Reform and Consumer Protection Act, Pub. L. No. 111-203","url":"https://www.govinfo.gov/link/plaw/111/public/203","by":{"0":"37"}},{"t":"law","label":"Pub. L. No. 104-67","url":"https://www.govinfo.gov/link/plaw/104/public/67","by":{"0":"37"}},{"t":"reg","label":"17 C.F.R. § 230.144","url":"https://www.ecfr.gov/current/title-17/section-230.144","subs":["(b)","(c)"],"by":{"0":"5, 20, 5","1":"5, 11, 12, 14, 26, 26","2":"14"}},{"t":"case","label":"Brief of the SEC, McKowan Lowe & Co. v. Jasmine, Ltd.","cite":"295 F.3d 380","y":2002,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/295/380/","op":3,"by":{"0":"35"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"1":"46","2":"22"}},{"t":"case","label":"Dolan v. U.S. Postal Serv.","cite":"546 U.S. 481","y":2006,"id":"2005/04-848","sc":1,"sum":"The Court ruled that the \"negligent transmission\" exception was inapplicable to Dolan's case, and therefore sovereign immunity had been waived and her case could proceed. The Court accepted Dolan's argument that the exception was only meant to encompass cases of late, missing, or incorrectly delivered mail.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Gallardo ex rel. Vassallo v. Marstiller","cite":"142 S. Ct. 1751","y":2022,"id":"2021/20-1263","sc":1,"sum":"The Medicaid Act permits a State to seek reimbursement from settlement payments allocated for future medical care.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"41"}},{"t":"case","label":"Goldman Sachs Grp., Inc. v. Ark. Tchr. Ret. Sys.","cite":"141 S. Ct. 1951","y":2021,"id":"2020/20-222","sc":1,"sum":"The generic nature of a misrepresentation in connection with the sale of securities often is important evidence of price impact that courts should consider at class certification; defendants bear the burden of persuasion to prove a lack of price impact by a preponderance of the evidence at class certification.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"49"}},{"t":"case","label":"Halliburton Co. v. Erica P. John Fund, Inc.","cite":"573 U.S. 258","y":2014,"id":"2013/13-317","sc":1,"sum":"The Court held that there is no undue burden in allowing defendants in securities fraud cases from presenting evidence regarding the alleged impact of the misinformation on stock prices.","sumSrc":"Oyez","by":{"1":"49"}},{"t":"case","label":"Kirkwood v. Taylor","cite":"590 F. Supp. 1375","y":1984,"court":"D. Minn.","url":"https://www.courtlistener.com/c/F.%20Supp./590/1375/","by":{"1":"36"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Matrixx Initiatives, Inc. v. Siracusano","cite":"563 U.S. 27","y":2011,"id":"2010/09-1156","sc":1,"sum":"The Court held that a plaintiff could state a claim based on a pharmaceutical company's non-disclosure of adverse event reports, even though the reports are not alleged to be statistically significant.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"34"}},{"t":"case","label":"Radzanower v. Touche Ross & Co.","cite":"426 U.S. 148","y":1976,"id":"1975/75-268","sc":1,"sum":"Venue in a suit against a national banking association charged with violating the Securities Exchange Act of 1934 held to be governed by the venue provision of the National Bank Act, 12 U. S. C. § 94, which provides that an action against a national banking association may be had in any federal district court within the district in which such association may be established, rather than by § 27 of the Securities …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34"}},{"t":"case","label":"SEC v. Chinese Consol. Benevolent Ass’n","cite":"120 F.2d 738","y":1941,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/120/738/","by":{"1":"26"}},{"t":"case","label":"SEC. v. Cap. Gains Rsch. Bureau, Inc.","cite":"375 U.S. 180","y":1963,"id":"1963/42","sc":1,"by":{"1":"29"}},{"t":"case","label":"Tsirekidze v. Syntax-Brillian Corp.","cite":"2009 WL 2151838","y":2009,"court":"D. Ariz. July 17","by":{"1":"36"}},{"t":"case","label":"Zenith Radio Corp. v. Hazeltine Rsch., Inc.","cite":"395 U.S. 100","y":1969,"id":"1968/49","sc":1,"sum":"Upon the expiration in 1959 of petitioner, Zenith's, license agreement with Hazeltine Research, Inc. (HRI), which permitted Zenith to use all of HRI's domestic radio and television patents under HRI's so-called standard package license, Zenith refused to renew, asserting that it no longer required a license. HRI brought a patent infringement suit in November 1959. Zenith's answer alleged invalidity of the patent, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"usc","label":"15 U.S.C. § 77a","url":"https://www.law.cornell.edu/uscode/text/15/77a","stext":{"head":"§77a. Short title","paras":[[0,"This subchapter may be cited as the \"Securities Act of 1933\"."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§77a. Short title","tname":"Commerce and Trade","by":{"1":"5, 40"}},{"t":"usc","label":"15 U.S.C. § 77h","url":"https://www.law.cornell.edu/uscode/text/15/77h","by":{"1":"4"}},{"t":"usc","label":"15 U.S.C. § 77m","url":"https://www.law.cornell.edu/uscode/text/15/77m","by":{"1":"7, 33"}},{"t":"usc","label":"15 U.S.C. § 77aa","url":"https://www.law.cornell.edu/uscode/text/15/77aa","by":{"1":"4, 25"}},{"t":"usc","label":"15 U.S.C. § 78a","url":"https://www.law.cornell.edu/uscode/text/15/78a","stext":{"head":"§78a. Short title","paras":[[0,"This chapter may be cited as the \"Securities Exchange Act of 1934.\""]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§78a. Short title","tname":"Commerce and Trade","by":{"1":"26"}},{"t":"usc","label":"15 U.S.C. § 78b","url":"https://www.law.cornell.edu/uscode/text/15/78b","subs":["(a)(11)"],"by":{"1":"26"}},{"t":"usc","label":"15 U.S.C. § 78f","url":"https://www.law.cornell.edu/uscode/text/15/78f","subs":["(a)","(b)(1)","(b)(5)"],"by":{"1":"27, 27, 27, 38"}},{"t":"usc","label":"15 U.S.C. § 78s","url":"https://www.law.cornell.edu/uscode/text/15/78s","subs":["(b)(2)(C)(i)"],"by":{"1":"27, 38"}},{"t":"reg","label":"Order Approving a Proposed Rule Change to Modify the Provisions Relating to Direct Listings, Exchange Act Release No. 34-90768, 85 Fed. Reg. 85,807","url":"https://www.govinfo.gov/link/fr/85/85807","by":{"1":"37","2":"10, 20"}},{"t":"reg","label":"Order Approving Proposed Rule Change To Determine That a Company Meets the Exchange’s Market Value Requirements by Relying on a Third-Party , 73 Fed. Reg. 54,442","url":"https://www.govinfo.gov/link/fr/73/54442","by":{"1":"10, 25"}},{"t":"reg","label":"Order Granting Accelerated Approval of Proposed Rule Change to Amend Section 102.01B of the NYSE Listed Company Manual, Exchange Act Release, 83 Fed. Reg. 5650","url":"https://www.govinfo.gov/link/fr/83/5650","by":{"1":"12, 25"}},{"t":"case","label":"Madden v. Cowen & Co.","cite":"576 F.3d 957","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/576/957/","by":{"2":"9"}},{"t":"case","label":"Perez v. Mortg. Bankers Ass’n","cite":"575 U.S. 92","y":2015,"id":"2014/13-1041","sc":1,"sum":"The Court ruled that federal agencies do not need to engage in a notice-and-comment procedure before significantly altering an interpretation of a rule of agency regulation.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"United States v. Jones","cite":"565 U.S. 400","y":2012,"id":"2011/10-1259","sc":1,"sum":"The Court found that a police department's placement of a GPS tracking device on a man's Jeep without his knowledge was an illegal search under the Fourth Amendment.","sumSrc":"Oyez","by":{"2":"22"}}]};